#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAggregate: FfiConverterRustBuffer {
    typealias SwiftType = Aggregate

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Aggregate {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .account(try FfiConverterTypeAccount.read(from: &buf)
        )

        case 2: return .financialRevision(try FfiConverterTypeFinancialRevision.read(from: &buf)
        )

        case 3: return .categoryGroup(try FfiConverterTypeCategoryGroup.read(from: &buf)
        )

        case 4: return .category(try FfiConverterTypeCategory.read(from: &buf)
        )

        case 5: return .payee(try FfiConverterTypePayee.read(from: &buf)
        )

        case 6: return .transaction(try FfiConverterTypeTransaction.read(from: &buf)
